class NbChatComponent {
  constructor(statusService) {
    this.statusService = statusService;
    /**
     * Chat status color (adds specific styles):
     * `basic` (default), `primary`, `success`, `info`, `warning`, `danger`, `control`.
     */

    this.status = 'basic';
    this.noMessagesPlaceholder = 'No messages yet.';
    this._scrollBottom = true;
  }
  /**
   * Scroll chat to the bottom of the list when a new message arrives
   */


  get scrollBottom() {
    return this._scrollBottom;
  }

  set scrollBottom(value) {
    this._scrollBottom = convertToBoolProperty(value);
  }

  ngOnChanges(changes) {
    if ('status' in changes) {
      this.updateFormStatus();
    }
  }

  ngAfterContentInit() {
    this.updateFormStatus();
  }

  ngAfterViewInit() {
    this.messages.changes.subscribe(messages => {
      this.messages = messages;
      this.updateView();
    });
    this.updateView();
  }

  updateView() {
    if (this.scrollBottom) {
      this.scrollListBottom();
    }
  }

  scrollListBottom() {
    this.scrollable.nativeElement.scrollTop = this.scrollable.nativeElement.scrollHeight;
  }

  updateFormStatus() {
    if (this.chatForm) {
      this.chatForm.setStatus(this.status);
    }
  }

  get tiny() {
    return this.size === 'tiny';
  }

  get small() {
    return this.size === 'small';
  }

  get medium() {
    return this.size === 'medium';
  }

  get large() {
    return this.size === 'large';
  }

  get giant() {
    return this.size === 'giant';
  }

  get primary() {
    return this.status === 'primary';
  }

  get success() {
    return this.status === 'success';
  }

  get info() {
    return this.status === 'info';
  }

  get warning() {
    return this.status === 'warning';
  }

  get danger() {
    return this.status === 'danger';
  }

  get basic() {
    return this.status === 'basic';
  }

  get control() {
    return this.status === 'control';
  }

  get additionalClasses() {
    if (this.statusService.isCustomStatus(this.status)) {
      return [this.statusService.getStatusClass(this.status)];
    }

    return [];
  }

}

